import{projetos,criarCardProjeto}from"./projetos.js";import{mostrarCadastro}from"./cadastro.js";import{mostrarToast,abrirModal,fecharModal,alternarMenu,alternarContraste}from"./interface.js";const app=document.getElementById("app");export function navegar(o){"inicio"===o&&mostrarInicio(),"projetos"===o&&mostrarProjetos(),"cadastro"===o&&mostrarCadastro(app)}function mostrarInicio(){app.innerHTML=`\n        <section class="inicio">\n\n            <h1>Bem-vindo à ONG Esperança</h1>\n\n            <p>\n                Juntos podemos transformar vidas e ajudar\n                quem mais precisa.\n            </p>\n\n            <div class="destaque">\n                ${criarCardProjeto(projetos[0])}\n            </div>\n\n            <button onclick="abrirModal()">\n                Saiba mais\n            </button>\n\n        </section>\n    `}function mostrarProjetos(){let o="";projetos.forEach(function(r){o+=criarCardProjeto(r)}),app.innerHTML=`\n        <section class="projetos">\n\n            <h2>Nossos Projetos</h2>\n\n            <div class="lista-projetos">\n                ${o}\n            </div>\n\n        </section>\n    `}window.navegar=navegar,window.abrirModal=abrirModal,window.fecharModal=fecharModal,window.alternarMenu=alternarMenu,window.alternarContraste=alternarContraste,window.mostrarToast=mostrarToast,navegar("inicio");